void reverse(int nums[], int nums_size) {
    int i = 0;
    int j = nums_size - 1;

    while (i < j) {
        int tmp = nums[i];
        nums[i] = nums[j];
        nums[j] = tmp;

        i++;
        j--;
    }
}

